function bofTitle(txt,cx,cy,H){
  /* PANEL FONT, NOT THE STAGE FONT (drop 0801bp). Mike: "fix the font up top in
     the options menu."

     This ran through msgText, which composites the per-stage BITMAP font - the
     distressed, chipped lettering meant for stage-name cards. Every other label
     on this panel (VOLUME, CONTROLS, MASTER, the key caps) is drawn in BOFmil,
     so the title was the one element in a different typeface entirely.

     Drawn in BOFmil directly at the panel's own accent colour, with a dark seat
     behind it so it still reads against a bright backdrop. */
  const h=H||16;
  ctx.save();
  ctx.textAlign='center'; ctx.textBaseline='middle';
  ctx.font='bold '+Math.round(h*1.35)+'px "BOFmil", monospace';
  const t=String(txt).toUpperCase();
  ctx.lineWidth=Math.max(3,Math.round(h*0.28)); ctx.strokeStyle='rgba(0,0,0,0.78)';
  ctx.strokeText(t,cx,cy+h*0.35);
  ctx.shadowColor='rgba(255,179,71,0.55)'; ctx.shadowBlur=10;
  ctx.fillStyle='#ffd36b'; ctx.fillText(t,cx,cy+h*0.35);
  ctx.restore(); ctx.textBaseline='alphabetic';
}

function drawCanonBackdrop(key, dim, drift){
  if(!(typeof XART!=='undefined' && XART.rdy(key))) return false;
  const im=XART.get(key), s=Math.max(VW/im.naturalWidth, VH/im.naturalHeight);
  const dw=im.naturalWidth*s, dh=im.naturalHeight*s;
  /* PARALLAX (drop 0801bp). Mike: "make the background parallax scroll."
     The plate was pinned dead centre, so the menus sat on a still image. It now
     drifts on two axes at different rates - a continuous vertical crawl with a
     slower horizontal sway - and is OVERSCALED 12% so the drift can never expose
     an edge. Callers that pass no drift keep the old static framing, so only the
     screens that opt in change. */
  const _d=(drift==null)?0:drift;
  let ox=0, oy=0, ew=dw, eh=dh;
  if(_d>0){
    const t=(performance.now()/1000)*_d;
    ew=dw*1.12; eh=dh*1.12;
    const mx=(ew-VW)/2, my=(eh-VH)/2;
    ox=Math.sin(t*0.11)*Math.min(mx,26);
    oy=(my>0)? (my - ((t*7)%(my*2))) : 0;
  }
  ctx.drawImage(im,(VW-ew)/2+ox,(VH-eh)/2+oy,ew,eh);
  const g=ctx.createLinearGradient(0,0,0,VH);
  g.addColorStop(0,'rgba(4,5,10,'+(dim*0.9)+')'); g.addColorStop(0.35,'rgba(4,5,10,'+(dim*0.35)+')'); g.addColorStop(1,'rgba(4,5,10,'+dim+')');
  ctx.fillStyle=g; ctx.fillRect(0,0,VW,VH);
  return true;
}

function _selKey(v){ return v==='r' ? 'nsel_arrow_r' : v==='g' ? 'nsel_arrow_g' : v==='y' ? 'nsel_arrow_y' : 'nsel_arrow'; }

function _selWhite(v){
  const key=_selKey(v);
  _selWhite._c = _selWhite._c || {};
  if(_selWhite._c[key]) return _selWhite._c[key];
  if(typeof XART==='undefined' || !XART.rdy(key)) return null;
  const im=XART.get(key);
  const cv=document.createElement('canvas');
  cv.width=im.naturalWidth; cv.height=im.naturalHeight;
  const g=cv.getContext('2d');
  g.drawImage(im,0,0);
  g.globalCompositeOperation='source-atop';       // paint only the arrow's own pixels
  g.fillStyle='#ffffff'; g.fillRect(0,0,cv.width,cv.height);
  _selWhite._c[key]=cv;
  return cv;
}

function drawSelArrow(x, y, h, mirror, variant){
  const key=_selKey(variant);
  if(typeof XART==='undefined') return false;
  if(XART._src && XART._src[key] && XART._touch) XART._touch(key);
  if(!XART.rdy(key)) return false;
  const im=XART.get(key);
  const w=h*(im.naturalWidth/im.naturalHeight);
  const t=(performance.now()/1000)%SEL_CYCLE;
  ctx.save();
  ctx.translate(x,y);
  if(mirror) ctx.rotate(Math.PI);
  ctx.shadowColor = (variant==='r') ? '#ffa08f' : (variant==='g') ? '#9fffb0' : (variant==='y') ? '#ffe9a0' : '#8fd8ff';
  ctx.shadowBlur=8;
  ctx.drawImage(im,-w/2,-h/2,w,h);
  const wc=_selWhite(variant);
  if(wc){
    ctx.shadowBlur=0;
    if(t<SEL_RISE){
      // rising band: white climbs from the bottom edge to the top
      const k=t/SEL_RISE;
      const bandTop = h/2 - h*k;                  // sweeps upward
      ctx.save();
      ctx.beginPath(); ctx.rect(-w/2, bandTop, w, h/2-bandTop); ctx.clip();
      ctx.globalAlpha=0.92;
      ctx.drawImage(wc,-w/2,-h/2,w,h);
      ctx.restore();
    } else if(t<SEL_RISE+SEL_FLASH){
      // reached the top -> the whole unit pops
      const k=(t-SEL_RISE)/SEL_FLASH;
      ctx.globalAlpha=1-k*0.35;
      ctx.drawImage(wc,-w/2,-h/2,w,h);
    }
    // else: rest, plain sprite
  }
  ctx.restore();
  return true;
}

function menuSelMark(cx, cy, halfW, tint){
  /* The caller passes a TINT COLOUR; map it to the matching duplicated cursor so
     the arrow path gets the real palette-swapped art rather than the flat
     source-atop fill used on the nss_cursor brackets below. */
  const _selVar = (tint==='#ff2a2a'||tint==='red') ? 'r'
                : (tint==='#2aff5a'||tint==='green') ? 'g'
                : (tint==='#ffd24a'||tint==='yellow') ? 'y' : null;
  const p = Math.sin(performance.now()/130)*2;
  const lx = cx-halfW-16-p, rx = cx+halfW+16+p;
  /* THE DUPLICATED CURSOR WINS (drop 0801bj). Mike asked for the MENU cursor -
     the nsel_arrow one the title screen uses - duplicated and palette-swapped
     per screen. This function's first branch draws the nss_cursor BRACKETS
     instead, which are different art entirely, so the red variant would never
     have been reached. When a screen asks for a variant and that art resolves,
     draw it and stop; the brackets stay as the fallback for screens that pass no
     tint at all. */
  if(_selVar && typeof drawSelArrow==='function'
     && drawSelArrow(lx, cy, 22, false, _selVar) && drawSelArrow(rx, cy, 22, true, _selVar)) return;
  if(typeof XART!=='undefined' && XART.rdy && XART.rdy('nss_cursor_0')){
    /* PALETTE SWAP. Same cursor art everywhere, tinted per screen — mode select uses RED. Tinted
       through a cached source-atop buffer, never getImageData (that is what killed the campaign
       map on file:// once already). */
    let im=XART.get('nss_cursor_'+(((performance.now()/70)|0)%8)); const cs=22;
    if(tint && im){
      menuSelMark._tc = menuSelMark._tc || {};
      const ck=tint+'_'+(((performance.now()/70)|0)%8);
      let cc=menuSelMark._tc[ck];
      if(!cc){
        const cv2=document.createElement('canvas');
        cv2.width=im.naturalWidth||cs; cv2.height=im.naturalHeight||cs;
        const g3=cv2.getContext('2d');
        g3.drawImage(im,0,0);
        g3.globalCompositeOperation='source-atop';
        g3.fillStyle=tint; g3.globalAlpha=0.92;
        g3.fillRect(0,0,cv2.width,cv2.height);
        cc=menuSelMark._tc[ck]=cv2;
      }
      im=cc;
    }
    /* MEASURE EITHER SOURCE. Once tinted, `im` is a CANVAS — canvases have width/height, NOT
       naturalWidth. The old guard read naturalWidth on the tinted buffer, got undefined, treated a
       perfectly good sprite as unloadable, fell out of the if/else and threw. And because
       requestAnimationFrame sits AFTER drawScene in the frame loop, that single throw killed the
       loop permanently — the hard lock on MODE SELECT. */
    const _iw=(im && (im.naturalWidth || im.width)) || 0;
    const _ih=(im && (im.naturalHeight || im.height)) || 0;
    if(!im || !_iw || !_ih){
      if(typeof drawSelArrow==='function'){ drawSelArrow(lx,cy,20,false,_selVar); drawSelArrow(rx,cy,20,true,_selVar); }
      return;
    }
    else {
    const ar=_iw/_ih, cw=cs*ar;
    ctx.save();
    ctx.drawImage(im, lx-cw/2, cy-cs/2, cw, cs);
    ctx.translate(rx,0); ctx.scale(-1,1); ctx.translate(-rx,0);
    ctx.drawImage(im, rx-cw/2, cy-cs/2, cw, cs);
    ctx.restore();
    return;
    }
  }
  if(typeof drawSelArrow==='function' && drawSelArrow(lx, cy, 20, false, _selVar) && drawSelArrow(rx, cy, 20, true, _selVar)) return;
  ctx.save();
  ctx.fillStyle='#ffe682'; ctx.font='bold 16px "BOFmil", monospace'; ctx.textAlign='center';
  ctx.fillText('\u25B6', lx, cy+5); ctx.fillText('\u25C0', rx, cy+5);
  ctx.restore();
}

function menuSelWhite(){
  const f=0.5+0.5*Math.sin(performance.now()/120);
  return f>0.55 ? '#ffffff' : '#ffe9a8';
}

